use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.is_empty() {
            Value::Null
        } else {
            let mut min_val = i64::MAX;
            let mut max_val = i64::MIN;
            for item in arr {
                if let Value::Number(num) = item {
                    if let Some(n) = num.as_i64() {
                        if n < min_val {
                            min_val = n;
                        }
                        if n > max_val {
                            max_val = n;
                        }
                    }
                }
            }
            Value::Array(vec![serde_json::Number::from(min_val), serde_json::Number::from(max_val)])
        }
    } else {
        Value::Null
    }
}
